import subprocess, re, collections
def sh(*a): return subprocess.run(a, capture_output=True, text=True).stdout
# collect all friend-message commits
labeled = collections.defaultdict(list)
for b in ["rachel","monica","phoebe","joey","chandler","ross"]:
    for sha in sh("git","log","--format=%H","origin/friend/"+b).split():
        body = sh("git","show","-s","--format=%B",sha)
        if re.search(r'^Friend-Message: 1', body, re.M):
            ep = re.search(r'^Episode: (\S+)', body, re.M)
            labeled[ep.group(1) if ep else "?"].append(("friend/"+b, sha))
filed = set()
files = {}
for season in ["S01","S02"]:
    for f in sh("git","ls-tree","--name-only","origin/main:"+season).split():
        p = season+"/"+f
        txt = sh("git","show","origin/main:"+p)
        files[p] = txt
        for m in re.finditer(r'^Source: (friend/\w+) @ ([0-9a-f]{40})', txt, re.M):
            filed.add((m.group(1), m.group(2)))
print("episodes on main:", sorted(files))
print("total labeled commits:", sum(len(v) for v in labeled.values()))
print("total filed sources:", len(filed))
missing = []
for ep, items in sorted(labeled.items()):
    for b, sha in items:
        if (b, sha) not in filed:
            missing.append((ep, b, sha))
print("\n=== MISSING (labeled but not in any episode file) ===")
for ep,b,sha in sorted(missing, key=lambda x: x[0]):
    print(ep, b, sha)
print("count:", len(missing))
# also: filed but not labeled (fabrications/foreign)
extra = [x for x in filed if not any(x in items for items in labeled.values())]
print("\n=== FILED but not found among labeled commits ===", len(extra))
for x in sorted(extra)[:20]: print(x)
